//! Format compatibility with the chrono build.
//!
//! Every expected string below is what chrono 0.4.45 produced for the same
//! instant (`Serialize`, `to_rfc3339()`, `Display`, `timestamp()`). They were
//! generated by a differential run against chrono before chrono left the
//! dependency tree, and they pin the persisted format from now on.

use super::*;

/// (unix seconds, subsecond nanos, chrono serde form, chrono `to_rfc3339`,
/// chrono `Display`).
const CHRONO_FORMS: &[(i64, u32, &str, &str, &str)] = &[
    (
        1_795_158_001,
        798_036_936,
        "2026-11-20T07:00:01.798036936Z",
        "2026-11-20T07:00:01.798036936+00:00",
        "2026-11-20 07:00:01.798036936 UTC",
    ),
    (
        1_795_158_143,
        405_665_000,
        "2026-11-20T07:02:23.405665Z",
        "2026-11-20T07:02:23.405665+00:00",
        "2026-11-20 07:02:23.405665 UTC",
    ),
    (
        1_795_158_143,
        120_000_000,
        "2026-11-20T07:02:23.120Z",
        "2026-11-20T07:02:23.120+00:00",
        "2026-11-20 07:02:23.120 UTC",
    ),
    (
        1_795_158_143,
        100,
        "2026-11-20T07:02:23.000000100Z",
        "2026-11-20T07:02:23.000000100+00:00",
        "2026-11-20 07:02:23.000000100 UTC",
    ),
    (
        1_795_158_143,
        1_000,
        "2026-11-20T07:02:23.000001Z",
        "2026-11-20T07:02:23.000001+00:00",
        "2026-11-20 07:02:23.000001 UTC",
    ),
    (
        1_795_158_143,
        0,
        "2026-11-20T07:02:23Z",
        "2026-11-20T07:02:23+00:00",
        "2026-11-20 07:02:23 UTC",
    ),
    (
        0,
        0,
        "1970-01-01T00:00:00Z",
        "1970-01-01T00:00:00+00:00",
        "1970-01-01 00:00:00 UTC",
    ),
    (
        -1,
        500_000_000,
        "1969-12-31T23:59:59.500Z",
        "1969-12-31T23:59:59.500+00:00",
        "1969-12-31 23:59:59.500 UTC",
    ),
    (
        -62_135_596_800,
        0,
        "0001-01-01T00:00:00Z",
        "0001-01-01T00:00:00+00:00",
        "0001-01-01 00:00:00 UTC",
    ),
    (
        253_402_207_199,
        999_000_000,
        "9999-12-30T21:59:59.999Z",
        "9999-12-30T21:59:59.999+00:00",
        "9999-12-30 21:59:59.999 UTC",
    ),
];

fn instant(seconds: i64, nanos: u32) -> UtcDateTime {
    UtcDateTime::from_timestamp(seconds, nanos).expect("in range")
}

#[test]
fn serde_form_matches_chrono_serialize() {
    for &(seconds, nanos, serde_form, _, _) in CHRONO_FORMS {
        let json = serde_json::to_string(&instant(seconds, nanos)).unwrap();
        assert_eq!(json, format!("\"{serde_form}\""), "for {seconds}.{nanos:09}");
    }
}

#[test]
fn to_rfc3339_matches_chrono() {
    for &(seconds, nanos, _, rfc3339, _) in CHRONO_FORMS {
        assert_eq!(instant(seconds, nanos).to_rfc3339(), rfc3339, "for {seconds}.{nanos:09}");
    }
}

#[test]
fn display_and_debug_match_chrono() {
    for &(seconds, nanos, serde_form, _, display) in CHRONO_FORMS {
        let value = instant(seconds, nanos);
        assert_eq!(value.to_string(), display);
        assert_eq!(format!("{value:?}"), serde_form);
    }
}

#[test]
fn every_chrono_form_parses_back_to_the_same_instant() {
    for &(seconds, nanos, serde_form, rfc3339, _) in CHRONO_FORMS {
        let expected = instant(seconds, nanos);
        assert_eq!(UtcDateTime::parse_from_rfc3339(serde_form).unwrap(), expected);
        assert_eq!(UtcDateTime::parse_from_rfc3339(rfc3339).unwrap(), expected);
        let from_json: UtcDateTime = serde_json::from_str(&format!("\"{serde_form}\"")).unwrap();
        assert_eq!(from_json, expected);
    }
}

#[test]
fn timestamp_floors_like_chrono_for_pre_epoch_fractions() {
    // chrono: timestamp() == -1 and subsec nanos == 500_000_000 for
    // 1969-12-31T23:59:59.5Z; jiff's own as_second() would truncate to 0.
    let value = UtcDateTime::parse_from_rfc3339("1969-12-31T23:59:59.5Z").unwrap();
    assert_eq!(value.timestamp(), -1);
    assert_eq!(value.timestamp_micros(), -500_000);

    let tiny = UtcDateTime::parse_from_rfc3339("1969-12-31T23:59:59.999999999Z").unwrap();
    assert_eq!(tiny.timestamp(), -1);
    assert_eq!(tiny.timestamp_micros(), -1);

    let after = UtcDateTime::parse_from_rfc3339("2026-11-20T07:00:01.798036936Z").unwrap();
    assert_eq!(after.timestamp(), 1_795_158_001);
    assert_eq!(after.timestamp_micros(), 1_795_158_001_798_036);
}

#[test]
fn from_timestamp_rejects_a_full_second_of_nanos_like_chrono() {
    assert!(UtcDateTime::from_timestamp(0, 1_000_000_000).is_none());
    assert!(UtcDateTime::from_timestamp(i64::MAX, 0).is_none());
}

#[test]
fn offsets_normalise_to_utc_and_compare_by_instant() {
    let toronto = UtcDateTime::parse_from_rfc3339("2026-11-20T02:00:00-05:00").unwrap();
    let utc = UtcDateTime::parse_from_rfc3339("2026-11-20T07:00:00Z").unwrap();
    assert_eq!(toronto, utc);
    assert_eq!(toronto.to_rfc3339(), "2026-11-20T07:00:00+00:00");
    assert_eq!(serde_json::to_string(&toronto).unwrap(), "\"2026-11-20T07:00:00Z\"");
}

#[test]
fn lenient_rfc3339_variants_chrono_accepted_still_parse() {
    let expected = UtcDateTime::parse_from_rfc3339("2026-11-20T07:02:23Z").unwrap();
    for input in [
        "2026-11-20 07:02:23Z",
        "2026-11-20t07:02:23z",
        "2026-11-20T07:02:23+00:00",
        "2026-11-20T02:02:23-05:00",
        "2026-11-20T07:02:23.000Z",
        " 2026-11-20T07:02:23Z ",
        "2026-11-20 07:02:23 +00:00",
        "2026-11-20 07:02:23 +0000",
        "2026-11-20 02:02:23 -05:00",
        "2026-11-20 07:02:23 UTC",
        "2026-11-20T07:02:23.0000000000Z",
    ] {
        assert_eq!(UtcDateTime::parse_from_rfc3339(input).unwrap(), expected, "{input}");
    }
}

#[test]
fn chrono_display_forms_parse_back_and_long_fractions_truncate() {
    for &(seconds, nanos, _, _, display) in CHRONO_FORMS {
        assert_eq!(UtcDateTime::parse_from_rfc3339(display).unwrap(), instant(seconds, nanos));
    }
    let long = UtcDateTime::parse_from_rfc3339("2026-11-20T07:02:23.1234567899Z").unwrap();
    assert_eq!(long.to_rfc3339(), "2026-11-20T07:02:23.123456789+00:00");
}

#[test]
fn days_matches_chrono_and_refuses_to_wrap() {
    assert_eq!(days(2), SignedDuration::from_hours(48));
    assert!(std::panic::catch_unwind(|| days(768_614_336_404_564_651)).is_err());
}

#[test]
fn timestamps_without_an_offset_are_rejected() {
    for input in ["2026-11-20T07:02:23", "2026-11-20", "not a time", ""] {
        assert!(UtcDateTime::parse_from_rfc3339(input).is_err(), "{input}");
        assert!(serde_json::from_str::<UtcDateTime>(&format!("\"{input}\"")).is_err());
    }
}

#[test]
fn optional_fields_round_trip_byte_for_byte() {
    #[derive(Serialize, Deserialize)]
    struct Record {
        at: UtcDateTime,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        settled_at: Option<UtcDateTime>,
    }
    let text = r#"{"at":"2026-11-20T07:02:23.405665746Z","settled_at":"2026-11-20T07:03:00.120Z"}"#;
    let record: Record = serde_json::from_str(text).unwrap();
    assert_eq!(serde_json::to_string(&record).unwrap(), text);

    let absent = r#"{"at":"2026-11-20T07:02:23Z"}"#;
    let record: Record = serde_json::from_str(absent).unwrap();
    assert_eq!(serde_json::to_string(&record).unwrap(), absent);
}

#[test]
fn arithmetic_matches_chrono_duration_semantics() {
    let start = UtcDateTime::parse_from_rfc3339("2026-03-08T01:30:00Z").unwrap();
    // UTC has no DST: a day is always 24 hours, as chrono's Duration::days.
    assert_eq!((start + days(1)).to_rfc3339(), "2026-03-09T01:30:00+00:00");
    assert_eq!(
        (start - SignedDuration::from_hours(2)).to_rfc3339(),
        "2026-03-07T23:30:00+00:00"
    );

    let later = start + SignedDuration::from_mins(90) + SignedDuration::from_millis(1);
    let elapsed = later - start;
    assert_eq!(elapsed.as_hours(), 1);
    assert_eq!(elapsed.as_mins(), 90);
    assert_eq!(elapsed.as_secs(), 5_400);

    // num_days()/num_hours() truncate toward zero for negative spans.
    let back = start - later;
    assert_eq!(back.as_hours(), -1);
    assert_eq!(back.as_mins(), -90);
}

#[test]
fn format_uses_utc() {
    let value = UtcDateTime::parse_from_rfc3339("2026-11-20T23:30:00-05:00").unwrap();
    assert_eq!(value.format("%Y-%m"), "2026-11");
    assert_eq!(value.format("%Y-%m-%d %H:%M UTC"), "2026-11-21 04:30 UTC");
    assert_eq!(value.format("%Y%m%dT%H%M%SZ"), "20261121T043000Z");
    assert_eq!(value.date().to_string(), "2026-11-21");
}
